**Step 3: Implement Capacity Monitoring**

Create background service monitoring capacity indicators:

```csharp
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Options;
using Prometheus;
using System.Diagnostics;

public class CapacityMonitorService : BackgroundService
{
    private readonly ILogger<CapacityMonitorService> _logger;
    private readonly ThrottlingOptions _options;
    private readonly Process _currentProcess;

    // Prometheus metrics
    private static readonly Gauge CpuUtilization = Metrics.CreateGauge(
        "throttling_cpu_utilization_percent",
        "Current CPU utilization percentage");
    private static readonly Gauge MemoryUtilization = Metrics.CreateGauge(
        "throttling_memory_utilization_percent",
        "Current memory utilization percentage");
    private static readonly Gauge DatabaseConnections = Metrics.CreateGauge(
        "throttling_database_connections_active",
        "Active database connections");
    private static readonly Gauge CapacityScore = Metrics.CreateGauge(
        "throttling_capacity_score",
        "Overall capacity health score (0-100)");

    public CapacityState CurrentState { get; private set; } = CapacityState.Healthy;

    public CapacityMonitorService(
        ILogger<CapacityMonitorService> logger,
        IOptions<ThrottlingOptions> options)
    {
        _logger = logger;
        _options = options.Value;
        _currentProcess = Process.GetCurrentProcess();
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("Capacity Monitor started");

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                var metrics = await CollectCapacityMetrics();
                var state = EvaluateCapacityState(metrics);

                if (state != CurrentState)
                {
                    _logger.LogWarning(
                        "Capacity state changed: {OldState} -> {NewState}. Metrics: CPU={Cpu}%, Memory={Memory}%, Connections={Connections}",
                        CurrentState, state, metrics.CpuPercent, metrics.MemoryPercent, metrics.DatabaseConnections);
                    CurrentState = state;
                }

                // Update Prometheus metrics
                CpuUtilization.Set(metrics.CpuPercent);
                MemoryUtilization.Set(metrics.MemoryPercent);
                DatabaseConnections.Set(metrics.DatabaseConnections);
                CapacityScore.Set(metrics.CapacityScore);

                await Task.Delay(TimeSpan.FromSeconds(5), stoppingToken);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error monitoring capacity");
            }
        }
    }

    private async Task<CapacityMetrics> CollectCapacityMetrics()
    {
        // CPU utilization (using exponentially weighted moving average)
        var cpuPercent = await GetCpuUtilizationAsync();

        // Memory utilization
        _currentProcess.Refresh();
        var memoryBytes = _currentProcess.PrivateMemorySize64;
        var memoryPercent = (memoryBytes / (double)GC.GetGCMemoryInfo().TotalAvailableMemoryBytes) * 100;

        // Database connections (requires custom tracking in DbContext)
        var dbConnections = DatabaseConnectionTracker.ActiveConnections;
        var dbConnectionPercent = (dbConnections / (double)_options.MaxDatabaseConnections) * 100;

        // Calculate composite capacity score (0-100, 100 = healthy)
        var capacityScore = CalculateCapacityScore(cpuPercent, memoryPercent, dbConnectionPercent);

        return new CapacityMetrics
        {
            CpuPercent = cpuPercent,
            MemoryPercent = memoryPercent,
            DatabaseConnections = dbConnections,
            DatabaseConnectionPercent = dbConnectionPercent,
            CapacityScore = capacityScore,
            Timestamp = DateTimeOffset.UtcNow
        };
    }

    private async Task<double> GetCpuUtilizationAsync()
    {
        // Measure CPU over 1 second interval
        var startTime = DateTime.UtcNow;
        var startCpuUsage = _currentProcess.TotalProcessorTime;

        await Task.Delay(1000);

        var endTime = DateTime.UtcNow;
        var endCpuUsage = _currentProcess.TotalProcessorTime;

        var cpuUsedMs = (endCpuUsage - startCpuUsage).TotalMilliseconds;
        var totalMsPassed = (endTime - startTime).TotalMilliseconds;
        var cpuUsageTotal = cpuUsedMs / (Environment.ProcessorCount * totalMsPassed);

        return cpuUsageTotal * 100;
    }

    private double CalculateCapacityScore(double cpu, double memory, double dbConnections)
    {
        // Weighted scoring: CPU 40%, Memory 30%, DB Connections 30%
        var cpuScore = Math.Max(0, 100 - cpu);
        var memoryScore = Math.Max(0, 100 - memory);
        var dbScore = Math.Max(0, 100 - dbConnections);

        return (cpuScore * 0.4) + (memoryScore * 0.3) + (dbScore * 0.3);
    }

    private CapacityState EvaluateCapacityState(CapacityMetrics metrics)
    {
        // Capacity states based on composite score
        if (metrics.CapacityScore >= 40) return CapacityState.Healthy;
        if (metrics.CapacityScore >= 25) return CapacityState.Degraded;
        if (metrics.CapacityScore >= 10) return CapacityState.Critical;
        return CapacityState.Overloaded;
    }
}

public enum CapacityState
{
    Healthy,    // Score >= 40: CPU <60%, Memory <70%, Connections <70%
    Degraded,   // Score 25-40: CPU 60-75%, Memory 70-85%, Connections 70-85%
    Critical,   // Score 10-25: CPU 75-90%, Memory 85-95%, Connections 85-95%
    Overloaded  // Score <10: CPU >90%, Memory >95%, Connections >95%
}

public class CapacityMetrics
{
    public double CpuPercent { get; set; }
    public double MemoryPercent { get; set; }
    public int DatabaseConnections { get; set; }
    public double DatabaseConnectionPercent { get; set; }
    public double CapacityScore { get; set; }
    public DateTimeOffset Timestamp { get; set; }
}
```

