#### Phase 2: Core Throttling Implementation (Week 3-4)

**Step 4: Implement Admission Controller Middleware**

Create ASP.NET Core middleware for request admission control:

```csharp
using Microsoft.AspNetCore.Http;
using Polly;
using Polly.RateLimiting;
using StackExchange.Redis;

public class ThrottlingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<ThrottlingMiddleware> _logger;
    private readonly CapacityMonitorService _capacityMonitor;
    private readonly IConnectionMultiplexer _redis;
    private readonly ThrottlingOptions _options;

    // Prometheus metrics
    private static readonly Counter RequestsAdmitted = Metrics.CreateCounter(
        "api_requests_admitted_total",
        "Total requests admitted immediately",
        new CounterConfiguration { LabelNames = new[] { "endpoint", "priority" } });
    private static readonly Counter RequestsQueued = Metrics.CreateCounter(
        "api_requests_queued_total",
        "Total requests queued for later processing",
        new CounterConfiguration { LabelNames = new[] { "endpoint", "priority" } });
    private static readonly Counter RequestsRejected = Metrics.CreateCounter(
        "api_requests_rejected_total",
        "Total requests rejected with 429",
        new CounterConfiguration { LabelNames = new[] { "endpoint", "reason" } });
    private static readonly Histogram RequestQueueWaitTime = Metrics.CreateHistogram(
        "api_request_queue_wait_seconds",
        "Time spent waiting in queue",
        new HistogramConfiguration { Buckets = Histogram.ExponentialBuckets(0.1, 2, 10) });

    public ThrottlingMiddleware(
        RequestDelegate next,
        ILogger<ThrottlingMiddleware> logger,
        CapacityMonitorService capacityMonitor,
        IConnectionMultiplexer redis,
        IOptions<ThrottlingOptions> options)
    {
        _next = next;
        _logger = logger;
        _capacityMonitor = capacityMonitor;
        _redis = redis;
        _options = options.Value;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (!_options.Enabled)
        {
            await _next(context);
            return;
        }

        var endpoint = context.GetEndpoint()?.DisplayName ?? "unknown";
        var consumerId = GetConsumerId(context);
        var priority = ClassifyPriority(context);

        try
        {
            // Check circuit breaker state for downstream dependencies
            if (await IsCircuitOpen(endpoint))
            {
                await RejectRequest(context, endpoint, "circuit_breaker_open",
                    "Downstream service unavailable", retryAfterSeconds: 30);
                return;
            }

            // Check consumer quota
            if (!await CheckConsumerQuota(consumerId))
            {
                await RejectRequest(context, endpoint, "quota_exceeded",
                    "Consumer quota exceeded", retryAfterSeconds: 60);
                return;
            }

            // Make admission decision based on capacity and priority
            var decision = MakeAdmissionDecision(priority, _capacityMonitor.CurrentState);

            switch (decision)
            {
                case AdmissionDecision.Admit:
                    // Increment quota counter and admit
                    await IncrementConsumerQuota(consumerId);
                    RequestsAdmitted.WithLabels(endpoint, priority.ToString()).Inc();
                    await _next(context);
                    break;

                case AdmissionDecision.Queue:
                    // Queue for later processing (if async pattern supported)
                    RequestsQueued.WithLabels(endpoint, priority.ToString()).Inc();
                    await QueueRequest(context, endpoint, priority);
                    break;

                case AdmissionDecision.Reject:
                    // Reject with 429
                    var retryAfter = CalculateRetryAfter(_capacityMonitor.CurrentState);
                    await RejectRequest(context, endpoint, "capacity_exceeded",
                        "Service at capacity", retryAfterSeconds: retryAfter);
                    break;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Throttling middleware error for endpoint {Endpoint}", endpoint);
            // Fail open - allow request through on throttling errors
            await _next(context);
        }
    }

    private string GetConsumerId(HttpContext context)
    {
        // Extract consumer ID from API key, JWT claim, or client certificate
        if (context.Request.Headers.TryGetValue("X-API-Key", out var apiKey))
        {
            return $"api-key:{apiKey}";
        }

        var user = context.User;
        if (user?.Identity?.IsAuthenticated == true)
        {
            var stateId = user.FindFirst("state_id")?.Value;
            var providerId = user.FindFirst("provider_id")?.Value;

            if (stateId != null) return $"state:{stateId}";
            if (providerId != null) return $"provider:{providerId}";

            return $"user:{user.Identity.Name}";
        }

        return $"anonymous:{context.Connection.RemoteIpAddress}";
    }

    private RequestPriority ClassifyPriority(HttpContext context)
    {
        // Check explicit priority header
        if (context.Request.Headers.TryGetValue("X-Priority", out var priorityHeader))
        {
            if (Enum.TryParse<RequestPriority>(priorityHeader, true, out var priority))
                return priority;
        }

        // Check endpoint configuration
        var endpoint = context.GetEndpoint();
        var priorityMetadata = endpoint?.Metadata.GetMetadata<PriorityAttribute>();
        if (priorityMetadata != null)
            return priorityMetadata.Priority;

        // Check consumer tier (premium consumers get higher priority)
        var user = context.User;
        if (user?.HasClaim("tier", "premium") == true)
            return RequestPriority.High;

        // Default to normal priority
        return RequestPriority.Normal;
    }

    private AdmissionDecision MakeAdmissionDecision(RequestPriority priority, CapacityState capacity)
    {
        // Critical priority always admitted (unless circuit breaker open)
        if (priority == RequestPriority.Critical)
            return AdmissionDecision.Admit;

        return capacity switch
        {
            CapacityState.Healthy => AdmissionDecision.Admit,
            CapacityState.Degraded => priority >= RequestPriority.High
                ? AdmissionDecision.Admit
                : AdmissionDecision.Queue,
            CapacityState.Critical => priority == RequestPriority.High
                ? AdmissionDecision.Queue
                : AdmissionDecision.Reject,
            CapacityState.Overloaded => AdmissionDecision.Reject,
            _ => AdmissionDecision.Reject
        };
    }

    private async Task<bool> CheckConsumerQuota(string consumerId)
    {
        var db = _redis.GetDatabase();
        var key = $"throttle:quota:{consumerId}";

        // Sliding window algorithm: count requests in last minute
        var now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        var windowStart = now - 60; // 60-second window

        // Use Lua script for atomic check-and-increment
        var script = @"
            local key = KEYS[1]
            local now = tonumber(ARGV[1])
            local window_start = tonumber(ARGV[2])
            local limit = tonumber(ARGV[3])

            -- Remove expired entries
            redis.call('ZREMRANGEBYSCORE', key, '-inf', window_start)

            -- Count requests in window
            local count = redis.call('ZCARD', key)

            if count < limit then
                return 1  -- Quota available
            else
                return 0  -- Quota exceeded
            end
        ";

        var result = await db.ScriptEvaluateAsync(script,
            new RedisKey[] { key },
            new RedisValue[] { now, windowStart, _options.DefaultQuotaPerMinute });

        return (int)result == 1;
    }

    private async Task IncrementConsumerQuota(string consumerId)
    {
        var db = _redis.GetDatabase();
        var key = $"throttle:quota:{consumerId}";
        var now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();

        // Add request to sorted set with timestamp as score
        await db.SortedSetAddAsync(key, now.ToString(), now);
        await db.KeyExpireAsync(key, TimeSpan.FromMinutes(2)); // Auto-cleanup
    }

    private int CalculateRetryAfter(CapacityState capacity)
    {
        return capacity switch
        {
            CapacityState.Degraded => 5,    // Retry after 5 seconds
            CapacityState.Critical => 15,   // Retry after 15 seconds
            CapacityState.Overloaded => 30, // Retry after 30 seconds
            _ => 10
        };
    }

    private async Task RejectRequest(HttpContext context, string endpoint, string reason,
        string message, int retryAfterSeconds)
    {
        RequestsRejected.WithLabels(endpoint, reason).Inc();

        context.Response.StatusCode = 429; // Too Many Requests
        context.Response.Headers["Retry-After"] = retryAfterSeconds.ToString();
        context.Response.Headers["X-Throttling-Reason"] = reason;
        context.Response.Headers["X-RateLimit-Limit"] = _options.DefaultQuotaPerMinute.ToString();
        context.Response.Headers["X-RateLimit-Reset"] =
            DateTimeOffset.UtcNow.AddSeconds(retryAfterSeconds).ToUnixTimeSeconds().ToString();

        await context.Response.WriteAsJsonAsync(new
        {
            error = "throttled",
            message = message,
            retry_after_seconds = retryAfterSeconds,
            reason = reason
        });

        _logger.LogWarning(
            "Request throttled: Endpoint={Endpoint}, Reason={Reason}, RetryAfter={RetryAfter}s",
            endpoint, reason, retryAfterSeconds);
    }

    private async Task QueueRequest(HttpContext context, string endpoint, RequestPriority priority)
    {
        // For async request pattern: queue to Service Bus, return 202 Accepted
        // For synchronous pattern: implement in-memory queue with bounded wait

        context.Response.StatusCode = 202; // Accepted
        context.Response.Headers["X-Queue-Position"] = "pending";
        context.Response.Headers["X-Estimated-Wait-Seconds"] = "12";

        await context.Response.WriteAsJsonAsync(new
        {
            status = "queued",
            message = "Request queued for processing",
            priority = priority.ToString(),
            estimated_wait_seconds = 12
        });
    }

    private async Task<bool> IsCircuitOpen(string endpoint)
    {
        var db = _redis.GetDatabase();
        var key = $"throttle:circuit:{endpoint}";
        var state = await db.StringGetAsync(key);
        return state == "open";
    }
}

public enum AdmissionDecision
{
    Admit,   // Process immediately
    Queue,   // Queue for later processing
    Reject   // Reject with HTTP 429
}

public enum RequestPriority
{
    Critical = 0,  // P0: Emergency, never throttled
    High = 1,      // P1: Important, throttled only under critical load
    Normal = 2,    // P2: Standard, throttled under degraded load
    Low = 3        // P3: Bulk operations, throttled first
}

// Attribute for endpoint-level priority configuration
[AttributeUsage(AttributeTargets.Method | AttributeTargets.Class)]
public class PriorityAttribute : Attribute
{
    public RequestPriority Priority { get; }
    public PriorityAttribute(RequestPriority priority) => Priority = priority;
}
```

