#### Example 2: Service Registration and Middleware Configuration

```csharp
// Program.cs: Configure throttling services
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using Prometheus;
using StackExchange.Redis;

var builder = WebApplication.CreateBuilder(args);

// Configure Redis
var redisConnection = ConnectionMultiplexer.Connect(
    builder.Configuration.GetConnectionString("Redis"));
builder.Services.AddSingleton<IConnectionMultiplexer>(redisConnection);

// Configure throttling options
builder.Services.Configure<ThrottlingOptions>(
    builder.Configuration.GetSection("Throttling"));

// Register capacity monitor as hosted service
builder.Services.AddSingleton<CapacityMonitorService>();
builder.Services.AddHostedService(sp => sp.GetRequiredService<CapacityMonitorService>());

// Add Prometheus metrics
builder.Services.AddSingleton(Metrics.DefaultRegistry);

// Add controllers
builder.Services.AddControllers();

// Add health checks
builder.Services.AddHealthChecks()
    .AddRedis(builder.Configuration.GetConnectionString("Redis"))
    .AddCheck<CapacityHealthCheck>("capacity");

var app = builder.Build();

// Enable Prometheus metrics endpoint
app.UseMetricServer(); // Exposes /metrics endpoint

// Enable throttling middleware (before routing)
app.UseMiddleware<ThrottlingMiddleware>();

// Standard middleware
app.UseRouting();
app.UseAuthentication();
app.UseAuthorization();

app.MapControllers();
app.MapHealthChecks("/health");

app.Run();
```

